#include <zephyr/sys/min_heap.h>
#include <zephyr/sys/__assert.h>
#include <string.h>
#include <errno.h>

static inline void *get_elem(const struct min_heap *heap, size_t index)
{
	return (void *)((uintptr_t)heap->storage + index * heap->elem_size);
}

static void swap_elem(struct min_heap *heap, size_t a, size_t b)
{
	if (a == b) {
		return;
	}

	uint8_t *elem_a = get_elem(heap, a);
	uint8_t *elem_b = get_elem(heap, b);

	for (size_t i = 0; i < heap->elem_size; i++) {
		uint8_t tmp = elem_a[i];

		elem_a[i] = elem_b[i];
		elem_b[i] = tmp;
	}
}

static void heapify_up(struct min_heap *heap, size_t index)
{
	while (index > 0) {
		size_t parent = (index - 1) / 2;

		if (heap->cmp(get_elem(heap, index), get_elem(heap, parent)) >= 0) {
			break;
		}
		swap_elem(heap, index, parent);
		index = parent;
	}
}

static void heapify_down(struct min_heap *heap, size_t index)
{
	while (true) {
		size_t left = 2 * index + 1;
		size_t right = 2 * index + 2;
		size_t smallest = index;

		if (left < heap->size &&
		    heap->cmp(get_elem(heap, left), get_elem(heap, smallest)) < 0) {
			smallest = left;
		}
		if (right < heap->size &&
		    heap->cmp(get_elem(heap, right), get_elem(heap, smallest)) < 0) {
			smallest = right;
		}
		if (smallest == index) {
			break;
		}
		swap_elem(heap, index, smallest);
		index = smallest;
	}
}

void min_heap_init(struct min_heap *heap, void *storage, size_t cap,
		   size_t elem_size, min_heap_cmp_t cmp)
{
	__ASSERT_NO_MSG(heap != NULL);
	__ASSERT_NO_MSG(storage != NULL);
	__ASSERT_NO_MSG(cap > 0);
	__ASSERT_NO_MSG(elem_size > 0);
	__ASSERT_NO_MSG(cmp != NULL);

	heap->storage = storage;
	heap->capacity = cap;
	heap->elem_size = elem_size;
	heap->size = 0;
	heap->cmp = cmp;
}

void *min_heap_peek(const struct min_heap *heap)
{
	__ASSERT_NO_MSG(heap != NULL);

	if (heap->size == 0) {
		return NULL;
	}

	return get_elem(heap, 0);
}

int min_heap_push(struct min_heap *heap, const void *item)
{
	__ASSERT_NO_MSG(heap != NULL);
	__ASSERT_NO_MSG(item != NULL);

	if (heap->size >= heap->capacity) {
		return -ENOMEM;
	}

	memcpy(get_elem(heap, heap->size), item, heap->elem_size);
	heapify_up(heap, heap->size);
	heap->size++;

	return 0;
}

bool min_heap_remove(struct min_heap *heap, size_t id, void *out_buf)
{
	__ASSERT_NO_MSG(heap != NULL);

	if (id >= heap->size) {
		return false;
	}

	if (out_buf != NULL) {
		memcpy(out_buf, get_elem(heap, id), heap->elem_size);
	}

	heap->size--;
	if (id < heap->size) {
		memcpy(get_elem(heap, id), get_elem(heap, heap->size), heap->elem_size);
		if (id > 0 && heap->cmp(get_elem(heap, id), get_elem(heap, (id - 1) / 2)) < 0) {
			heapify_up(heap, id);
		} else {
			heapify_down(heap, id);
		}
	}

	return true;
}

bool min_heap_pop(struct min_heap *heap, void *out_buf)
{
	return min_heap_remove(heap, 0, out_buf);
}

void *min_heap_find(struct min_heap *heap, min_heap_eq_t eq,
		    const void *other, size_t *out_id)
{
	__ASSERT_NO_MSG(heap != NULL);
	__ASSERT_NO_MSG(eq != NULL);

	for (size_t i = 0; i < heap->size; i++) {
		void *elem = get_elem(heap, i);

		if (eq(elem, other)) {
			if (out_id != NULL) {
				*out_id = i;
			}
			return elem;
		}
	}

	return NULL;
}
